'use client'

import * as React from 'react'

import './expand-search.css'

export type ExpandSearchProps = {
    /** Called with the query on submit. */
    onSearch?: (query: string) => void
    placeholder?: string
    /** Accessible name for the field and the button. */
    label?: string
    className?: string
}

// A search button that widens into a field. The button reports aria-expanded,
// focus moves into the field on open, and Escape closes it and returns focus.
const ExpandSearch = ({ onSearch, placeholder = 'Search…', label = 'Search', className }: ExpandSearchProps) => {
    const [open, setOpen] = React.useState(false)
    const [query, setQuery] = React.useState('')
    const inputRef = React.useRef<HTMLInputElement | null>(null)
    const buttonRef = React.useRef<HTMLButtonElement | null>(null)
    const inputId = React.useId()

    React.useEffect(() => { if (open) inputRef.current?.focus() }, [open])

    const close = () => { setOpen(false); buttonRef.current?.focus() }

    return <form
        role="search"
        className={['rad-fx-search', className].filter(Boolean).join(' ')}
        data-state={open ? 'open' : 'closed'}
        onSubmit={(event) => { event.preventDefault(); onSearch?.(query) }}
    >
        <button
            ref={buttonRef}
            type="button"
            className="rad-fx-search-toggle"
            aria-label={label}
            aria-expanded={open}
            aria-controls={inputId}
            onClick={() => (open ? close() : setOpen(true))}
        >
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="11" cy="11" r="6.5" /><path d="M16 16 L20.5 20.5" /></svg>
        </button>
        <input
            ref={inputRef}
            id={inputId}
            type="search"
            className="rad-fx-search-input"
            aria-label={label}
            placeholder={placeholder}
            value={query}
            tabIndex={open ? 0 : -1}
            aria-hidden={!open || undefined}
            onChange={(event) => setQuery(event.target.value)}
            onKeyDown={(event) => { if (event.key === 'Escape') { event.preventDefault(); close() } }}
        />
    </form>
}

export default ExpandSearch

.rad-fx-search {
    display: inline-flex;
    align-items: center;
    height: 44px;
    border: 1px solid rgba(127, 127, 127, 0.45);
    border-radius: 999px;
    overflow: hidden;
    transition: border-color 200ms ease;
}

.rad-fx-search:focus-within { border-color: currentColor; }

.rad-fx-search-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 42px;
    height: 42px;
    flex-shrink: 0;
    padding: 0;
    border: 0;
    border-radius: 999px;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

.rad-fx-search-toggle:focus-visible { outline: 2px solid currentColor; outline-offset: -4px; }

.rad-fx-search-toggle svg {
    width: 20px;
    height: 20px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
}

.rad-fx-search-input {
    width: 0;
    padding: 0;
    border: 0;
    outline: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    opacity: 0;
    transition: width 420ms cubic-bezier(0.3, 0.8, 0.2, 1), opacity 250ms ease, padding 420ms ease;
}

.rad-fx-search[data-state='open'] .rad-fx-search-input {
    width: 220px;
    padding-right: 16px;
    opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-search-input { transition: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-search-input { transition: none; }
